object-type.inject-code:
// PySide's QWidget typesystem adds callable addAction() overloads to every
// derived wrapper, but Shiboken does not repeat QWidget's native glue there.
// Keep an equivalent local bridge so those inherited overloads compile on
// both the Qt for Python 6.2 baseline and newer generators. Qt 6.2 only has
// QWidget::addAction(QAction *), so construct the actions explicitly instead
// of calling convenience overloads added by newer Qt releases.
static PyObject *connectCommandBarAction(
    QAction *action,
    PyObject *callback)
{
    PyObject *pyAction = %CONVERTTOPYTHON[QAction *](action);
    Shiboken::AutoDecRef result(PyObject_CallMethod(
        pyAction,
        "connect",
        "OsO",
        pyAction,
        SIGNAL(triggered()),
        callback));
    if (result.isNull()) {
        Py_DECREF(pyAction);
        return nullptr;
    }
    return pyAction;
}

static inline PyObject *addActionWithPyObject(
    QWidget *self,
    const QString &text,
    PyObject *callback)
{
    auto *action = new QAction(text, self);
    self->addAction(action);
    return connectCommandBarAction(action, callback);
}

static inline PyObject *addActionWithPyObject(
    QWidget *self,
    const QIcon &icon,
    const QString &text,
    PyObject *callback)
{
    auto *action = new QAction(icon, text, self);
    self->addAction(action);
    return connectCommandBarAction(action, callback);
}

static inline PyObject *addActionWithPyObject(
    QWidget *self,
    const QString &text,
    const QKeySequence &shortcut,
    PyObject *callback)
{
    auto *action = new QAction(text, self);
    action->setShortcut(shortcut);
    self->addAction(action);
    return connectCommandBarAction(action, callback);
}

static inline PyObject *addActionWithPyObject(
    QWidget *self,
    const QIcon &icon,
    const QString &text,
    const QKeySequence &shortcut,
    PyObject *callback)
{
    auto *action = new QAction(icon, text, self);
    action->setShortcut(shortcut);
    self->addAction(action);
    return connectCommandBarAction(action, callback);
}

static void syncCommandBarActionReference(
    SbkObject *self,
    fluent::menus_toolbars::CommandBar *bar,
    QAction *action,
    PyObject *pyAction)
{
    static const char primaryKey[] = "CommandBar.primaryActions";
    static const char secondaryKey[] = "CommandBar.secondaryActions";
    Shiboken::Object::removeReference(self, primaryKey, pyAction);
    Shiboken::Object::removeReference(self, secondaryKey, pyAction);
    if (bar->primaryActions().contains(action))
        Shiboken::Object::keepReference(self, primaryKey, pyAction, true);
    else if (bar->secondaryActions().contains(action))
        Shiboken::Object::keepReference(self, secondaryKey, pyAction, true);
}

// See CommandBar's wrapper-local QWidget addAction() compatibility bridge.
static PyObject *connectCommandBarFlyoutAction(
    QAction *action,
    PyObject *callback)
{
    PyObject *pyAction = %CONVERTTOPYTHON[QAction *](action);
    Shiboken::AutoDecRef result(PyObject_CallMethod(
        pyAction,
        "connect",
        "OsO",
        pyAction,
        SIGNAL(triggered()),
        callback));
    if (result.isNull()) {
        Py_DECREF(pyAction);
        return nullptr;
    }
    return pyAction;
}

static inline PyObject *addActionWithPyObject(
    QWidget *self,
    const QString &text,
    PyObject *callback)
{
    auto *action = new QAction(text, self);
